def compute(vars):
    values = {
        "December 27, 2019": vars["v1"],
        "December 28, 2018": vars["v2"],
        "December 29, 2017": vars["v3"],
    }
    highest_year = max(values, key=values.get)
    return {
        "value": highest_year,
        "trace": {
            "values": values,
            "highest_amount": values[highest_year],
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
